# run_selftest内への追加案（未実行）
current = PATHS.to_h { |key, path| [key, File.read(path)] }
frozen = PATHS.to_h { |key, path| [key, git_show('bdbf1d9', path)] }
selftest_assert inspect_product(current, frozen).empty?, '実製品の正例'
original = extract_modifier_closure(current[:markdown], 'heading4')
changed = original.sub('.fixedSize(horizontal: false, vertical: true)', '')
selftest_assert changed != original, '単一変異を適用'
bad = mutate(current, :markdown) { |src| src.sub(original, changed) }
